def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    p = s.get('element_properties') or {}
    n = len(sites)
    r = [float((p.get((t or {}).get('element')) or {}).get('covalent_radius_A') or 0.0) for t in sites]
    o = [max(0.0, float((t or {}).get('occupancy') if (t or {}).get('occupancy') is not None else 1.0)) for t in sites]
    total = 0.0
    value = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        if r[i] <= 0 or r[j] <= 0:
            continue
        x = d / (r[i] + r[j])
        if x <= 2.0:
            w = o[i] * o[j] / (1.0 + (x / 1.2) ** 12)
            total += w
            value += w * x
    return float(value / total) if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    p = s.get('element_properties') or {}
    n = len(sites)
    r = [float((p.get((t or {}).get('element')) or {}).get('covalent_radius_A') or 0.0) for t in sites]
    o = [max(0.0, float((t or {}).get('occupancy') if (t or {}).get('occupancy') is not None else 1.0)) for t in sites]
    value = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        if r[i] > 0 and r[j] > 0:
            x = d / (r[i] + r[j])
            if x < 1.0:
                value += o[i] * o[j] * (1.0 - x) ** 2
    total = sum(o)
    return float(0.5 * value / total) if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    p = s.get('element_properties') or {}
    n = len(sites)
    els = [(t or {}).get('element') for t in sites]
    r = [float((p.get(el) or {}).get('covalent_radius_A') or 0.0) for el in els]
    o = [max(0.0, float((t or {}).get('occupancy') if (t or {}).get('occupancy') is not None else 1.0)) for t in sites]
    total = 0.0
    hetero = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        if r[i] <= 0 or r[j] <= 0:
            continue
        x = d / (r[i] + r[j])
        if x <= 2.0:
            w = o[i] * o[j] / (1.0 + (x / 1.2) ** 12)
            total += w
            if els[i] != els[j]:
                hetero += w
    return float(hetero / total) if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    p = s.get('element_properties') or {}
    n = len(sites)
    props = [p.get((t or {}).get('element')) or {} for t in sites]
    r = [float(t.get('covalent_radius_A') or 0.0) for t in props]
    en = [t.get('eneg') for t in props]
    o = [max(0.0, float((t or {}).get('occupancy') if (t or {}).get('occupancy') is not None else 1.0)) for t in sites]
    weights = [0.0 for i in range(n)]
    values = [0.0 for i in range(n)]
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        if r[i] <= 0 or r[j] <= 0 or en[j] is None:
            continue
        x = d / (r[i] + r[j])
        if x <= 2.0:
            w = o[j] / (1.0 + (x / 1.2) ** 12)
            weights[i] += w
            values[i] += w * en[j]
    z = sum(o[i] for i in range(n) if weights[i] > 0)
    if z <= 0:
        return 0.0
    mean = sum(o[i] * values[i] / weights[i] for i in range(n) if weights[i] > 0) / z
    return float(sqrt(sum(o[i] * (values[i] / weights[i] - mean) ** 2 for i in range(n) if weights[i] > 0) / z))

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    p = s.get('element_properties') or {}
    n = len(sites)
    els = [(t or {}).get('element') for t in sites]
    r = [float((p.get(el) or {}).get('covalent_radius_A') or 0.0) for el in els]
    o = [max(0.0, float((t or {}).get('occupancy') if (t or {}).get('occupancy') is not None else 1.0)) for t in sites]
    nonmetals = ('H', 'B', 'C', 'N', 'O', 'F', 'Si', 'P', 'S', 'Cl', 'Se', 'Br', 'Te', 'I')
    value = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        if els[i] != els[j] or els[i] not in nonmetals or r[i] <= 0 or r[j] <= 0:
            continue
        x = d / (r[i] + r[j])
        if x <= 2.0:
            value += o[i] * o[j] / (1.0 + (x / 1.2) ** 12)
    total = sum(o)
    return float(0.5 * value / total) if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    neighbors = s.get('neighbors') or []
    nearest = [0.0 for i in range(n)]
    occ = [max(0.0, float((t or {}).get('occupancy') if (t or {}).get('occupancy') is not None else 1.0)) for t in sites]
    for b in neighbors:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0 or occ[j] <= 0:
            continue
        if nearest[i] == 0 or d < nearest[i]:
            nearest[i] = d
    moment = [[0.0 for k in range(3)] for a in range(3)]
    for b in neighbors:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        if nearest[i] <= 0 or d > 1.5 * nearest[i]:
            continue
        fi = (sites[i] or {}).get('frac_coords')
        fj = (sites[j] or {}).get('frac_coords')
        image = b.get('image')
        if fi is None or fj is None or image is None or len(fi) != 3 or len(fj) != 3 or len(image) != 3:
            continue
        delta = [fj[a] + image[a] - fi[a] for a in range(3)]
        vector = [sum(delta[a] * matrix[a][k] for a in range(3)) for k in range(3)]
        norm2 = sum(v * v for v in vector)
        if norm2 <= 0:
            continue
        w = occ[i] * occ[j] * exp(-4.0 * (d / nearest[i] - 1.0))
        for a in range(3):
            for k in range(3):
                moment[a][k] += w * vector[a] * vector[k] / norm2
    trace = sum(moment[a][a] for a in range(3))
    if trace <= 0:
        return 0.0
    purity = sum(moment[a][k] ** 2 for a in range(3) for k in range(3)) / (trace * trace)
    return float(max(0.0, min(1.0, 1.5 * (purity - 1.0 / 3.0))))

def feature(s):
    s = s or {}
    values = [float(x) for x in (s.get('composition') or {}).values() if x is not None and isfinite(x) and x > 0]
    total = sum(values)
    if total <= 0:
        return 0.0
    return float(-sum((x / total) * log(x / total) for x in values))

