def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    v = s.get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return 0.0
    total = 0.0
    weight = 0.0
    for site in sites:
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        o = site.get('occupancy')
        if o is None:
            o = 1.0
        if r is not None and isfinite(r) and r > 0 and isfinite(o) and o > 0:
            total = total + o * r ** 3
            weight = weight + o
    return 4.0 * pi * total / (3.0 * weight * v) if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    edges = s.get('neighbors') or []
    total = 0.0
    count = 0
    for i in range(len(sites)):
        r = radii[i]
        if r is not None and isfinite(r) and r > 0:
            values = [b['distance_A'] / (r + radii[b['j']]) for b in edges if b.get('i') == i and b.get('j') is not None and 0 <= b['j'] < len(sites) and b.get('distance_A') is not None and isfinite(b['distance_A']) and b['distance_A'] > 0 and radii[b['j']] is not None and isfinite(radii[b['j']]) and radii[b['j']] > 0]
            if values:
                total = total + min(values)
                count = count + 1
    return total / count if count else 0.0

